327	func TestKVDeterministic(t *testing.T) {
328		initial := InitialState{CurrentTerm: 1, CommittedIndex: 1, Log: []LogEntry{
329			entry(1, 1, "set a=1"),
330		}}
331		requests := []AppendRequest{
332			{Term: 1, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3,
333				Entries: []LogEntry{entry(2, 1, "set b=2"), entry(3, 1, "delete a")}},
334		}
335		first := runKV(t, initial, requests...)
336		second := runKV(t, initial, requests...)
337		if !reflect.DeepEqual(first, second) {
338			t.Fatalf("non-deterministic output:\n%+v\n%+v", first, second)
339		}
340		encoded1, err := json.Marshal(first)
341		if err != nil {
342			t.Fatal(err)
343		}
344		encoded2, err := json.Marshal(second)
345		if err != nil {
346			t.Fatal(err)
347		}
