353	// roundTrip 把输出编码为 JSON 再解码、再编码，模拟调用方保存或转交结果。
354	func roundTrip(t *testing.T, out ReplicateOutput) (ReplicateOutput, string) {
355		t.Helper()
356		encoded, err := json.Marshal(out)
357		if err != nil {
358			t.Fatal(err)
359		}
360		var decoded ReplicateOutput
361		if err := json.Unmarshal(encoded, &decoded); err != nil {
362			t.Fatal(err)
363		}
364		reencoded, err := json.Marshal(decoded)
365		if err != nil {
366			t.Fatal(err)
367		}
368		return decoded, string(reencoded)
369	}
