244		original := append([]LogEntry(nil), initial.Log...)
245		// idx2 处有可追加……实际这里 idx2 任期相同命令不同；idx3 任期不同且未提交。
246		out := run(t, initial,
247			AppendRequest{Term: 4, PrevLogIndex: 1, PrevLogTerm: 2,
248				Entries: []LogEntry{entry(2, 3, "X"), entry(3, 4, "f")}},
249		)
250		if out.Results[0].Accepted || !strings.Contains(out.Results[0].Reason, "conflict") {
251			t.Fatalf("expected command-conflict rejection, got %+v", out.Results[0])
252		}
253		if !reflect.DeepEqual(out.FinalLog, original) {
254			t.Fatalf("partial change left behind: %+v", out.FinalLog)
255		}
256	}
