318	func TestInvalidRequestDoesNotTouchStateOrTerm(t *testing.T) {
319		initial := InitialState{CurrentTerm: 2, CommittedIndex: 1,
320			Log: []LogEntry{entry(1, 2, "a")}}
321		out := run(t, initial,
322			// 非法：条目索引没有从 prevLogIndex+1 开始；还携带更高任期 9。
323			AppendRequest{Term: 9, PrevLogIndex: 1, PrevLogTerm: 2,
324				Entries: []LogEntry{entry(5, 9, "x")}},
325			// 非法：空任期。
326			AppendRequest{Term: 3, PrevLogIndex: 0, PrevLogTerm: 0,
327				Entries: []LogEntry{entry(1, 0, "x")}},
328			// 非法：条目任期下降。
329			AppendRequest{Term: 5, PrevLogIndex: 0, PrevLogTerm: 0,
330				Entries: []LogEntry{entry(1, 5, "x"), entry(2, 4, "y")}},
331			// 非法：条目任期超过请求任期。
332			AppendRequest{Term: 3, PrevLogIndex: 0, PrevLogTerm: 0,
333				Entries: []LogEntry{entry(1, 4, "x")}},
334			// 非法：负的 leaderCommit。
335			AppendRequest{Term: 3, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: -1},
336		)
