340			}
341			if result.Term != 2 || result.CommittedIndex != 1 {
342				t.Fatalf("result %d changed state: %+v", i, result)
343			}
344		}
345		if out.FinalTerm != 2 || out.FinalCommittedIndex != 1 {
346			t.Fatalf("final state changed: term=%d ci=%d", out.FinalTerm, out.FinalCommittedIndex)
347		}
