393	func TestDeterministicJSONRoundTrip(t *testing.T) {
394		initial := InitialState{CurrentTerm: 2, Log: []LogEntry{entry(1, 2, "a")}}
395		requests := []AppendRequest{
396			{Term: 3, PrevLogIndex: 1, PrevLogTerm: 2, LeaderCommit: 2,
397				Entries: []LogEntry{entry(2, 3, "b")}},
398			{Term: 2, PrevLogIndex: 2, PrevLogTerm: 3}, // stale term
399		}
400		first, err := Replicate(initial, requests)
401		if err != nil {
402			t.Fatal(err)
403		}
404		second, err := Replicate(initial, requests)
405		if err != nil {
406			t.Fatal(err)
407		}
408		if !reflect.DeepEqual(first, second) {
409			t.Fatalf("non-deterministic output:\n%+v\n%+v", first, second)
410		}
411		encoded, err := json.Marshal(first)
412		if err != nil {
413			t.Fatal(err)
414		}
415		var decoded ReplicateOutput
416		if err := json.Unmarshal(encoded, &decoded); err != nil {
417			t.Fatal(err)
418		}
